// Wrap an icon body in a card-sized SVG. currentColor lets CSS tint it.
export function iconSvg(id: string, cls = 'lu-icon'): string {
  const body = UPGRADE_ICONS[id];
  if (!body) return '';
  return `<svg class="${cls}" viewBox="0 0 512 512" aria-hidden="true" fill="currentColor">${body}</svg>`;
}

// Canvas variant (pause boons list): build a Path2D from all the `d` attributes in
// the icon body, in the source 512x512 space. Cached per id. Callers scale/translate.
const _paths: Record<string, Path2D | null> = {};
export function iconPath(id: string): Path2D | null {
  if (id in _paths) return _paths[id];
  const body = UPGRADE_ICONS[id];
  if (!body) return (_paths[id] = null);
  const path = new Path2D();
  for (const m of body.matchAll(/ d="([^"]+)"/g)) path.addPath(new Path2D(m[1]));
  return (_paths[id] = path);
}
export const ICON_VIEWBOX = 512;
